-- Additive generalized academic-rule architecture and Program 4 seed data.
BEGIN;
CREATE TABLE IF NOT EXISTS curriculum_components (
  component_id BIGSERIAL PRIMARY KEY, program_id VARCHAR NOT NULL REFERENCES programs(program_id),
  component_name TEXT NOT NULL, component_order INTEGER NOT NULL, required_credits NUMERIC,
  notes TEXT, UNIQUE(program_id, component_name));
CREATE TABLE IF NOT EXISTS curriculum_component_courses (
  component_id BIGINT NOT NULL REFERENCES curriculum_components(component_id),
  course_id VARCHAR NOT NULL REFERENCES courses(course_id), course_role TEXT NOT NULL DEFAULT 'REQUIRED',
  study_mode TEXT NOT NULL DEFAULT 'ALL', PRIMARY KEY(component_id, course_id, course_role, study_mode));
CREATE TABLE IF NOT EXISTS academic_rule_sets (
  rule_set_id BIGSERIAL PRIMARY KEY, program_id VARCHAR NOT NULL REFERENCES programs(program_id),
  rule_scope TEXT NOT NULL, rule_name TEXT NOT NULL, study_mode TEXT, exact_choice_count INTEGER,
  source_url TEXT, notes TEXT, UNIQUE(program_id, rule_scope, rule_name, study_mode));
CREATE TABLE IF NOT EXISTS academic_rule_groups (
  rule_group_id BIGSERIAL PRIMARY KEY, rule_set_id BIGINT NOT NULL REFERENCES academic_rule_sets(rule_set_id),
  parent_group_id BIGINT REFERENCES academic_rule_groups(rule_group_id), operator TEXT NOT NULL CHECK(operator IN ('AND','OR')),
  label TEXT, sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS academic_rule_conditions (
  condition_id BIGSERIAL PRIMARY KEY, rule_group_id BIGINT NOT NULL REFERENCES academic_rule_groups(rule_group_id),
  condition_type TEXT NOT NULL, subject_id TEXT, minimum_value NUMERIC, unit TEXT,
  accepted_values JSONB, parameters JSONB NOT NULL DEFAULT '{}'::jsonb, description TEXT NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS credit_requirements (
  credit_requirement_id BIGSERIAL PRIMARY KEY, program_id VARCHAR NOT NULL REFERENCES programs(program_id),
  component_id BIGINT REFERENCES curriculum_components(component_id), requirement_name TEXT NOT NULL,
  minimum_credits NUMERIC NOT NULL, study_mode TEXT, allows_external_courses BOOLEAN NOT NULL DEFAULT FALSE,
  approval_required BOOLEAN NOT NULL DEFAULT FALSE, notes TEXT, UNIQUE(program_id, requirement_name, study_mode));
CREATE TABLE IF NOT EXISTS credit_requirement_courses (
  credit_requirement_id BIGINT NOT NULL REFERENCES credit_requirements(credit_requirement_id),
  course_id VARCHAR NOT NULL REFERENCES courses(course_id), PRIMARY KEY(credit_requirement_id, course_id));
CREATE TABLE IF NOT EXISTS curriculum_substitutions (
  substitution_id BIGSERIAL PRIMARY KEY, program_id VARCHAR NOT NULL REFERENCES programs(program_id),
  study_mode TEXT NOT NULL, replaced_course_id VARCHAR REFERENCES courses(course_id),
  replacement_type TEXT NOT NULL, replacement_credits NUMERIC, description TEXT NOT NULL);
ALTER TABLE prerequisite_conditions ADD COLUMN IF NOT EXISTS parameters JSONB NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE prerequisite_conditions ADD COLUMN IF NOT EXISTS description TEXT;
SELECT setval('prerequisite_groups_prerequisite_group_id_seq', COALESCE((SELECT MAX(prerequisite_group_id) FROM prerequisite_groups), 1), true);
SELECT setval('prerequisite_conditions_prerequisite_condition_id_seq', COALESCE((SELECT MAX(prerequisite_condition_id) FROM prerequisite_conditions), 1), true);
VALUES ('8800BTECH','Construction Management','Bachelor of Technology Construction Management degree-completion program developing management, technical, and interpersonal construction-project skills.','ENG','School of Construction and the Environment','Bachelor of Technology / Bachelor''s Degree','Degree completion (Years 3 and 4)','Full-time and Part-time',TRUE,'Burnaby','In person','Active','https://www.bcit.ca/programs/construction-management-bachelor-of-technology-full-time-part-time-8800btech/','Two-year degree-completion program providing Years 3 and 4 of a four-year bachelor''s degree.')
ON CONFLICT (program_id) DO UPDATE SET program_name=EXCLUDED.program_name, program_overview=EXCLUDED.program_overview, area_id=EXCLUDED.area_id, school=EXCLUDED.school, credential=EXCLUDED.credential, program_level=EXCLUDED.program_level, study_mode=EXCLUDED.study_mode, campus=EXCLUDED.campus, delivery_method=EXCLUDED.delivery_method, status=EXCLUDED.status, source_url=EXCLUDED.source_url, notes=EXCLUDED.notes;



SELECT '8800BTECH',component_id,'Management elective credits',4,TRUE,TRUE,'Approved external management courses may satisfy this requirement.' FROM curriculum_components WHERE program_id='8800BTECH' AND component_name='Management Electives' ON CONFLICT(program_id,requirement_name,study_mode) DO NOTHING;
SELECT cr.credit_requirement_id, ccc.course_id FROM credit_requirements cr JOIN curriculum_component_courses ccc ON ccc.component_id=cr.component_id WHERE cr.program_id='8800BTECH' AND cr.requirement_name='Management elective credits' ON CONFLICT DO NOTHING;
SELECT '8800BTECH',component_id,'Liberal Studies total',12,'9 mandatory credits plus 3 elective credits.' FROM curriculum_components WHERE program_id='8800BTECH' AND component_name='Liberal Studies Component' ON CONFLICT(program_id,requirement_name,study_mode) DO NOTHING;
SELECT '8800BTECH','Part-time','LIBS7013','CREDIT_POOL',3,'Part-time students may take 3 additional approved Liberal Studies elective credits instead of LIBS 7013.' WHERE NOT EXISTS (SELECT 1 FROM curriculum_substitutions WHERE program_id='8800BTECH' AND study_mode='Part-time' AND replaced_course_id='LIBS7013');

-- Admission: common requirements AND exactly one complete pathway.
WITH rs AS (INSERT INTO academic_rule_sets(program_id,rule_scope,rule_name,exact_choice_count,source_url,notes) VALUES ('8800BTECH','ADMISSION','Construction Management admission',1,'https://www.bcit.ca/programs/construction-management-bachelor-of-technology-full-time-part-time-8800btech/#entry','Mandatory pre-entry assessment, common English, and exactly one of four pathways.') ON CONFLICT(program_id,rule_scope,rule_name,study_mode) DO UPDATE SET exact_choice_count=1 RETURNING rule_set_id),
root AS (INSERT INTO academic_rule_groups(rule_set_id,operator,label,sort_order) SELECT rule_set_id,'AND','Admission requirements',1 FROM rs RETURNING rule_group_id,rule_set_id),
paths AS (INSERT INTO academic_rule_groups(rule_set_id,parent_group_id,operator,label,sort_order) SELECT rule_set_id,rule_group_id,'OR','Exactly one entry pathway',3 FROM root RETURNING rule_group_id,rule_set_id)
SELECT root.rule_group_id,v.* FROM root CROSS JOIN (VALUES
('PRE_ENTRY_ASSESSMENT',NULL,NULL,NULL,'Approved departmental pre-entry assessment before application',1),
('ENGLISH_GRADE','ENGLISH_STUDIES_12',73,'PERCENT','English Studies 12 at 73% or equivalent',2)) v(condition_type,subject_id,minimum_value,unit,description,sort_order);

DO $$ DECLARE rs BIGINT; paths BIGINT; g BIGINT; BEGIN
SELECT rule_set_id INTO rs FROM academic_rule_sets WHERE program_id='8800BTECH' AND rule_scope='ADMISSION';
SELECT rule_group_id INTO paths FROM academic_rule_groups WHERE rule_set_id=rs AND label='Exactly one entry pathway';
FOR g IN SELECT rule_group_id FROM academic_rule_groups WHERE rule_set_id=rs AND parent_group_id=paths LOOP DELETE FROM academic_rule_conditions WHERE rule_group_id=g; DELETE FROM academic_rule_groups WHERE rule_group_id=g; END LOOP;
END $$;


-- Generalized non-course prerequisite conditions and exact course prerequisite groups.
ON CONFLICT(course_id) DO NOTHING;


-- CMGT 8700 generalized non-course/capstone conditions.
SELECT pg.prerequisite_group_id,v.condition_type,v.minimum_grade,v.parameters::jsonb,v.description,v.description FROM prerequisite_groups pg CROSS JOIN (VALUES
('PROGRAM_COURSES_COMPLETE_EXCEPT',NULL,'{"except":["CMGT8800","CMGT8810"]}','Successful completion of all program courses except the final project'),
('WORK_EXPERIENCE','2','{"unit":"YEAR","field":"related","admission_experience_counts":true}','Minimum 2 years related work experience total'),
('INDUSTRY_TOPIC',NULL,'{}','Approved industry topic'),('INDUSTRY_SPONSOR',NULL,'{}','Industry sponsor')) v(condition_type,minimum_grade,parameters,description)
WHERE pg.course_id='CMGT8700' AND NOT EXISTS(SELECT 1 FROM prerequisite_conditions pc WHERE pc.prerequisite_group_id=pg.prerequisite_group_id AND pc.condition_type=v.condition_type);
COMMIT;
